SELECT 'core-2026-09-v4','there-is-there-are','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"there-is-there-are","title":"There is and there are","level":"A1","order":8,"summary":"Describe what exists, ask about it, and give short answers.","learningGoals":["Existence and number","Questions and negatives","Short answers"],"guidance":"Read the rules and examples, then try a 20-question session. Explain why your chosen form fits the context and revisit any missed skill.","rules":[{"title":"Existence and number","explanation":"Use there is before a singular or uncountable noun. Use there are before a plural noun. These exercises use standard written agreement.","examples":["There is a light above the gate.","There are two seats near the exit."]},{"title":"Questions and negatives","explanation":"Put is or are before there to ask a question. Put not after the verb to make a negative.","examples":["Is there a bicycle stand?","There are not any spare chairs."]},{"title":"Short answers","explanation":"Keep there and the matching verb in a short answer. In a positive answer, do not shorten there is to there’s.","examples":["Yes, there is.","No, there are not."]}],"tips":["Check both the meaning and the form before answering.","Use the explanation to understand a mistake before moving on.","A practice result is feedback, not an official language certificate."],"source":"seed","provenance":{"version":"foundations-2026-09-v2","authorship":"Grammacho; generated offline with AI assistance","kind":"original-guidance-aligned","reviewStatus":"automated-checked; educator-review-pending","referenceIds":["bc-there-is-there-are"],"assessment":"Practice only; approximate teaching labels, not validated CEFR assessment."},"chapter":{"introduction":["Existential there introduces the presence of something. It lets a new thing enter the conversation naturally: There is a café nearby. This differs from The café is nearby, which starts from an already identified café. The verb reflects the number or amount introduced."],"rules":[{"title":"Existence and number","explanation":"Use there is before a singular or uncountable noun. Use there are before a plural noun. These exercises use standard written agreement.","examples":["There is a light above the gate.","There are two seats near the exit.","There **is** a clock above the door."],"pattern":"There **is** a seat / There **are** two seats","paragraphs":["Use there is with a singular count noun or an uncountable amount. Use there are with plural count nouns. In There is some equipment, equipment is uncountable and takes singular agreement even if it includes many separate objects."],"id":"there-is-there-are-foundation-1","domain":"information","referenceIds":["bc-there-is-there-are"],"readingVersion":"foundations-2026-09-v2"},{"title":"Questions and negatives","explanation":"Put is or are before there to ask a question. Put not after the verb to make a negative.","examples":["Is there a bicycle stand?","There are not any spare chairs.","There **are not** any spare tickets."],"pattern":"**Is there** a seat? / There **is not** a seat.","paragraphs":["Move is or are before there in a question. Put not after it in a negative. Any is common before a plural or uncountable noun in open questions and negatives: Are there any chairs? There isn’t any water."],"id":"there-is-there-are-foundation-2","domain":"information","referenceIds":["bc-there-is-there-are"],"readingVersion":"foundations-2026-09-v2"},{"title":"Short answers","explanation":"Keep there and the matching verb in a short answer. In a positive answer, do not shorten there is to there’s.","examples":["Yes, there is.","No, there are not.","**Is there** enough time? — Yes, there **is**."],"pattern":"Yes, there **is**. / No, there **is not**.","paragraphs":["A short answer keeps there and the auxiliary: Yes, there are. The positive short answer does not normally end in a contraction such as Yes, there’s. Here there is a grammatical subject, not a location meaning over there."],"id":"there-is-there-are-foundation-3","domain":"information","referenceIds":["bc-there-is-there-are"],"readingVersion":"foundations-2026-09-v2"},{"title":"Contrasts and edge cases","explanation":"Informal speech sometimes uses there’s before a list or plural, but these exercises practise standard written number agreement. Other tenses are possible: there was, there were, there will be and there has been. Distinguish there, their and they’re: they have different grammatical jobs.","examples":["There **is** a clock above the door.","There **are not** any spare tickets.","**Is there** enough time? — Yes, there **is**."],"id":"there-is-there-are-foundation-4","domain":"information","referenceIds":["bc-there-is-there-are"],"readingVersion":"foundations-2026-09-v2"},{"domain":"information","id":"existential-presentational-there","title":"Existential there, agreement and presentational constructions","explanation":"Existential there introduces the presence or occurrence of something, often new information. It is different from locative there, which points to a place. The construction can contain tense, modals or other verbs of appearance and existence. Formal agreement commonly reflects the following noun phrase; informal there’s before a plural is widespread.","pattern":"**There may be** a delay.","examples":["**There seems to be** a mistake.","**There remain several questions**."],"commonMistakes":["There is is often awkward for introducing an already identified person in a neutral existence statement. Context can license definite noun phrases in lists and other special uses."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["There **is** a seat / There **are** two seats","**Is there** a seat? / There **is not** a seat.","Yes, there **is**. / No, there **is not**."],"readingVersion":"core-2026-09-v4"},"stage":"1 · Sentence foundations","prerequisites":["possessive-s"],"readingReferenceIds":["bc-there-is-there-are","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='there-is-there-are'
